"""Reviewed per-column formulas and usage; consumed by the forward migration generator."""
from engine import COLUMNS, PATTERNS, library_contract

SWING_NULL_RULES = {
 'smi': 'NULL for an uncomputed ticker, invalid OHLCV, or a zero double-smoothed range; no zero imputation.',
 'tracking_high': 'Uncomputed/invalid row NULL; valid processed row is INTEGER 1 while tracking or 0 otherwise, including initialization.',
 'tracking_low': 'Uncomputed/invalid row NULL; valid processed row is INTEGER 1 while tracking or 0 otherwise, including initialization.',
 'temp_high': 'NULL outside active high tracking, including immediately after confirmation; uncomputed/invalid rows NULL.',
 'temp_high_bar': 'NULL together with temp_high; uncomputed/invalid rows NULL. Zero is a valid first-bar index.',
 'temp_low': 'NULL outside active low tracking, including immediately after confirmation; uncomputed/invalid rows NULL.',
 'temp_low_bar': 'NULL together with temp_low; uncomputed/invalid rows NULL. Zero is a valid first-bar index.',
 'last_swing_high': 'NULL before the first confirmed high or after invalid-row state reset; uncomputed rows NULL.',
 'break_swing_high': 'Valid processed row INTEGER 1 on a crossover, otherwise INTEGER 0, including before any confirmed high. NULL only for uncomputed/invalid rows.',
}


def specifications():
    contract=library_contract()
    specs={
      'ticker':('Identity','Security code copied from the classified price source ticker.','ticker','1 source row','symbol','Identify a security within its asset type.','Join with asset_type and the exact ticker; do not infer historical universe membership.'),
      'trade_date':('Identity','Trading observation date copied from source date.','date','1 source row','date','Order each security history and match exact observed dates.','This is the bar date, not its publication or prediction timestamp.'),
      'timeframe':('Identity','Verified daily timeframe copied exactly from source.','timeframe = Daily','1 source row','interval','Partition only daily observations.','No intraday or fabricated weekly/monthly bars are represented.'),
      'asset_type':('Identity','Universe-derived asset class for the ticker.','equity iff ticker is in IDX_Stock_Universe; bonds iff ticker is in Universe_Fixed_income','1 classified ticker','asset class','Partition identical ticker codes and select the correct price source.','Never hardcode ticker membership; missing or dual membership is rejected.'),
      'close':('Price','Daily closing price copied from the matching classified source row.','Price_Stock_Indonesia_IDX.close for equity; Price_Fixed_Income.close where metric_type=price, Timeframe=1D, and is_final=true for bonds; exact ticker and trade_date match','1 source row','source price unit','Use the observed close on trade_date directly alongside its derived indicators.','This is an unadjusted source level, not a return, prediction, or cross-asset comparable value.'),
      'sma_20':('Price','Unweighted mean of 20 observed closes.','TA-Lib SMA(close,20)','20 valid bars','source price unit','Use as a rolling price baseline.','A level is not a return; avoid comparing raw levels across tickers.'),
      'sma_50':('Price','Unweighted mean of 50 observed closes.','TA-Lib SMA(close,50)','50 valid bars','source price unit','Use as a longer rolling price baseline.','Do not fill insufficient history or infer a predictive crossing rule.'),
      'ema_12':('Price','Fast exponentially weighted close; alpha=2/13.','Seed=SMA(first12 closes); EMA[t]=EMA[t-1]+2/13*(close[t]-EMA[t-1])','12 valid bars; full available history used','source price unit','Measure the recent price baseline with greater recent weight.','Seed sensitivity persists beyond the first valid bar; raw price levels are not comparable returns.'),
      'ema_26':('Price','Slow exponentially weighted close; alpha=2/27.','Seed=SMA(first26 closes); EMA[t]=EMA[t-1]+2/27*(close[t]-EMA[t-1])','26 valid bars; full available history used','source price unit','Measure the slower price baseline against EMA12.','Seed and source corrections affect every later recursive value.'),
      'ema_50':('Price','Fifty-observation exponentially weighted close; alpha=2/51.','Seed=SMA(first50 closes); EMA[t]=EMA[t-1]+2/51*(close[t]-EMA[t-1])','50 valid bars; full available history used','source price unit','Use a medium-horizon price baseline.','Seed and adjustment vintage affect the whole later path; a crossing is not a validated prediction.'),
      'ema_200':('Price','Two-hundred-observation exponentially weighted close; alpha=2/201.','Seed=SMA(first200 closes); EMA[t]=EMA[t-1]+2/201*(close[t]-EMA[t-1])','200 valid bars; full available history used','source price unit','Use a long-horizon price baseline.','Short histories remain NULL; seed convergence and TradingView parity are not guaranteed by reaching bar 200.'),
      'adx_14':('Price Positioning','Wilder average directional index measuring trend strength on a 0–100 scale.','TA-Lib ADX(high,low,close,14); directional movement and true range Wilder-smoothed over 14, DX=100*abs(+DI-(-DI))/(+DI+(-DI)), then 14-period Wilder ADX; native zero-denominator convention; unstable period 0','28 valid bars; full available history used','index points','Describe trend strength independently of trend direction.','ADX is not bullish/bearish direction, a probability, or a verified predictive threshold; TradingView 14/14 initialization parity NOT VERIFIED.'),
      'inside_bar':('Price Positioning','Strict current-candle range containment within the previous valid observed candle.','1 if high[t]<high[t-1] AND low[t]>low[t-1], else 0; compare original numeric prices; no future candle','2 consecutive valid observed OHLCV bars','binary flag','Identify compression on the current closed Daily candle; allow other simultaneous patterns.','Equal boundaries are not inside bars under this strict rule. NULL means no usable predecessor; this is distinct from three-candle CDL3INSIDE and is not breakout direction or probability.'),
      'rsi_14':('Price Positioning','Wilder gain/loss oscillator on 14 consecutive close changes, scaled 0–100.','TA-Lib RSI(close,14): SMA seed of 14 gains/losses; RMA alpha=1/14; 100*gain/(gain+loss); both-zero uses native 0','15 valid bars; full available history used','index points','Use relative momentum as a numeric covariate.','Bounds do not provide probabilities; native flat-price 0 and TradingView edge-case parity are not verified.'),
      'macd':('Price Positioning','Difference of the stored fast and slow EMA price baselines.','ema_12 - ema_26; independently SMA-seeded EMAs, not TA-Lib MACD internal fast reseeding','26 valid bars; full available history used','source price unit','Use signed fast-minus-slow momentum relative to its price scale.','Magnitude depends on price level; no direct cross-stock ranking or guaranteed signal.'),
      'macd_signal':('Price Positioning','Nine-period EMA of valid MACD line observations.','Seed=SMA(first9 valid macd); signal[t]=signal[t-1]+0.2*(macd[t]-signal[t-1])','34 valid bars; full available history used','source price unit','Compare the line with a smoothed momentum baseline.','Signal seed/history can differ from TradingView; crossings have no validated hit rate.'),
      'macd_histogram':('Price Positioning','Difference between MACD line and its nine-period signal.','macd - macd_signal','34 valid bars','source price unit','Measure signed deviation of momentum from its smoothed baseline.','Histogram sign is descriptive; it does not predict the next return.'),
      'atr_14':('Volatility','Wilder average of 14 true ranges using prior observed close.','TA-Lib ATR(high,low,close,14): TR=max(high-low,abs(high-prev_close),abs(low-prev_close)); first TR excludes bar1; SMA seed then RMA alpha=1/14','15 valid bars; full available history used','source price unit','Measure absolute price-range volatility, without direction.','TradingView may include first-bar high-low; ATR levels depend on price scale and are not direction signals.'),
      'bb_upper_20':('Volatility','Upper 20-period Bollinger band, population standard deviation multiplier 2.','SMA20(close) + 2*sqrt(sum((close-SMA20)^2)/20)','20 valid bars','source price unit','Measure an upper dispersion boundary around SMA20.','A band is not a confidence interval or calibrated reversal probability.'),
      'bb_middle_20':('Price','Middle 20-period Bollinger band, identical to SMA20.','SMA20(close)','20 valid bars','source price unit','Provide the center of the paired Bollinger boundaries.','It duplicates sma_20; account for this redundancy in later model design.'),
      'bb_lower_20':('Volatility','Lower 20-period Bollinger band, population standard deviation multiplier 2.','SMA20(close) - 2*sqrt(sum((close-SMA20)^2)/20)','20 valid bars','source price unit','Measure a lower dispersion boundary around SMA20.','Bands can be crossed repeatedly; do not treat them as fixed support or predictive thresholds.'),
      'calculation_version':('Metadata','Version binds formulas, seeds and pinned TA-Lib versions.','engine.VERSION','1 calculation','version','Group or audit rows under an exact reproducible implementation.','Never treat a version identifier as a numerical training feature.'),
      'calculated_at':('Metadata','Timezone-aware execution time of the last changed output row.','UTC execution timestamp; unchanged UPSERT preserves existing timestamp','1 calculation','timestamp','Audit the calculation execution independently of the bar date.','A calculation timestamp is not historical source availability or publication time.'),
    }
    for col,name in PATTERNS.items():
        info=contract['patterns'][name]
        title=col[4:].replace('_',' ')
        specs[col]=('Price Positioning',f'Native TA-Lib {title} pattern recognition code from historical OHLC.',
                    f"TA-Lib {name}(open,high,low,close), default candle settings; parameters={info['parameters']}; native signed integers including non-100 codes retained",
                    f"{info['lookback']+1} valid OHLCV bars; lookback={info['lookback']}",'signed pattern code',
                    f'Use {title} recognition as an independent numerical covariate, allowing coexisting patterns.',
                    'Zero means available non-detection; NULL means unavailable. Sign is native library convention, not a probability or proof of IDX predictive value. TradingView candlestick equivalence NOT VERIFIED.')
    specs.update({
      'smi': ('Price Positioning','Stochastic Momentum Index: double-smoothed close displacement from the midpoint of a rolling 14-bar high/low range.',
              '200*EMA5(EMA5(close-(highest14(high)+lowest14(low))/2))/EMA5(EMA5(highest14(high)-lowest14(low))); first-input EMA seed, alpha=1/3, partial extrema windows at startup',
              'First valid OHLCV bar with nonzero smoothed range; full available history','index points',
              'Describe close position within the smoothed range and drive the supplied ±40 swing state transitions.',
              'This SMI is not RSI, stochastic %K, or a separate SMI signal line; Pine chart history/adjustment parity NOT VERIFIED.'),
      'tracking_high': ('Price Positioning','High-search state after all current-bar Pine blocks execute.',
                        'Set 1 on SMI crossover above +40, reset 0 on SMI crossunder below +40; initial 0; recross above +40 resets the temporary peak',
                        'Previous and current SMI to detect a threshold cross','binary state',
                        'Identify bars in an active high-tracking interval.',
                        'Not a confirmed swing-high event or price-breakout signal; SMI equal to +40 does not itself end tracking.'),
      'tracking_low': ('Price Positioning','Low-search state after all current-bar Pine blocks execute.',
                       'Set 1 on SMI crossunder below -40, reset 0 on SMI crossover above -40; initial 0; recross below -40 resets the temporary trough',
                       'Previous and current SMI to detect a threshold cross','binary state',
                       'Identify bars in an active low-tracking interval.',
                       'Not a confirmed swing-low event or breakout direction; the original script does not retain lastSwingLow.'),
      'temp_high': ('Price','Provisional highest high in the current active SMI-above-40 tracking interval.',
                    'Initialize high on +40 upcross; update only if tracking_high and SMI>40 and high>temp_high; clear on +40 downcross after copying to last_swing_high',
                    'Active tracking history only','source price unit',
                    'Inspect the candidate peak while high tracking is active.',
                    'Provisional level; the confirmation bar high is excluded, equal highs keep the first occurrence, and confirmation clears this column.'),
      'temp_high_bar': ('Metadata','Zero-based source observation index of the currently tracked temporary high.',
                        'bar_index on temp_high initialization or strictly higher high; index 0 is earliest available source row for this ticker and timeframe; NULL when temp_high is cleared',
                        'Full available ordered ticker history','bar index',
                        'Locate the provisional peak within this ticker history.',
                        'Not a date or a stable global/chart identifier; prepending source history shifts indices. Never backdate a confirmed feature to this bar.'),
      'temp_low': ('Price','Provisional lowest low in the current active SMI-below-minus-40 tracking interval.',
                   'Initialize low on -40 downcross; update only if tracking_low and SMI<-40 and low<temp_low; clear on -40 upcross',
                   'Active tracking history only','source price unit',
                   'Inspect the candidate trough while low tracking is active.',
                   'Provisional level; the confirmation bar low is excluded. No last_swing_low level is retained in the supplied script.'),
      'temp_low_bar': ('Metadata','Zero-based source observation index of the currently tracked temporary low.',
                       'bar_index on temp_low initialization or strictly lower low; index 0 is earliest available source row for this ticker and timeframe; NULL when temp_low is cleared',
                       'Full available ordered ticker history','bar index',
                       'Locate the provisional trough within this ticker history.',
                       'Not a date or stable chart identifier; prepended history shifts indices. A displayed historical label does not prove the trough was confirmed then.'),
      'last_swing_high': ('Price','Latest swing-high price available after its SMI-downcross confirmation, carried forward.',
                         'When tracking_high and SMI[t]<40 and SMI[t-1]>=40, copy tracked temp_high before clearing it; retain until the next high confirmation',
                         'One completed high-tracking interval','source price unit',
                         'Use the most recently confirmed swing level as known at the current close.',
                         'Becomes available on confirmation date, not the earlier peak date. It is not cleared after a breakout, and the level may move up or down.'),
      'break_swing_high': ('Price Positioning','Integer event flag for the supplied Pine close/last-swing-high crossover.',
                          '1 iff last_swing_high[t] and last_swing_high[t-1] exist AND close[t]>last_swing_high[t] AND close[t-1]<=last_swing_high[t-1]; otherwise 0 on a valid processed bar',
                          'Current and previous closes/confirmed levels','binary event',
                          'Filter value 1 and use trade_date as the closed Daily trigger date; SUM counts trigger bars among computed rows.',
                          'A wick alone does not trigger. Literal Pine compares changing current/prior levels, so a lowered newly confirmed level can contribute to a trigger. No one-shot lock or SMI-at-break filter; repeated triggers are possible. Not a trade instruction or win probability.'),
    })
    assert set(specs)==set(COLUMNS)
    return specs
